"""Budgets: allowances per calendar period and how the spending compares."""
import datetime as _dt
import re
from decimal import Decimal
from fractions import Fraction

from tallybook._util import is_date
from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.money import Money, round_div


class BudgetError(ValidationError):
    """A malformed budget or budget request."""


PERIOD_KINDS = ("month", "quarter", "year")
_KIND_ORDER = {k: i for i, k in enumerate(PERIOD_KINDS)}
_KIND_MONTHS = {"month": 1, "quarter": 3, "year": 12}
_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def _check_pattern(pattern):
    if not isinstance(pattern, str):
        raise BudgetError("budget pattern must be text, got %r" % (pattern,))
    if not pattern:
        raise BudgetError("budget pattern must not be empty")
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT_RE.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': each segment must be an account name "
                              "segment or *" % pattern)
    return tuple(pattern.split(":"))


def pattern_matches(pattern, path):
    """True when the budget pattern names `path` or an account above it."""
    pat = _check_pattern(pattern)
    return _match(pat, path.split(":"))


def _match(pat, segs):
    if len(segs) < len(pat):
        return False
    for p, s in zip(pat, segs):
        if p != "*" and p != s:
            return False
    return True


class Budget:
    """An allowance of `amount` per calendar `period_kind`, from the period containing `start`."""

    __slots__ = ("_pattern", "_period_kind", "_amount", "_start", "_segs")

    def __init__(self, pattern, period_kind, amount, start):
        segs = _check_pattern(pattern)
        if not isinstance(period_kind, str) or period_kind not in PERIOD_KINDS:
            raise BudgetError("invalid budget period kind %r: expected month, quarter or year"
                              % (period_kind,))
        if not isinstance(amount, Money):
            raise BudgetError("budget amount must be Money, got %r" % (amount,))
        if amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero, got %s" % (amount,))
        if not is_date(start):
            raise BudgetError("budget start must be a date, got %r" % (start,))
