            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": a, "amount": _money_dict(m)} for a, m in self.accounts],
        }


def _money_dict(m):
    return {"amount": m.amount_str(), "currency": m.currency}


# -- allowance ------------------------------------------------------------

def _month_index(d):
    return d.year * 12 + d.month - 1


def _calendar_start_index(d, kind):
    """Month index of the first month of the calendar period of `kind` containing d."""
    months = _KIND_MONTHS[kind]
    idx = _month_index(d)
    return idx - (idx % months) if months != 12 else d.year * 12


def _period_bounds(idx, kind):
    """(first day, last day) of the calendar period starting at month index idx."""
    months = _KIND_MONTHS[kind]
    y, m0 = divmod(idx, 12)
    ey, em0 = divmod(idx + months - 1, 12)
    return _dt.date(y, m0 + 1, 1), _dt.date(ey, em0 + 1, last_day(ey, em0 + 1))


def _allowance_fraction(budget, period):
    """Sum of overlap fractions, or None when the budget is not in force in the period."""
    kind = budget.period_kind
    months = _KIND_MONTHS[kind]
    first_idx = _calendar_start_index(budget.start, kind)
    first_start, _ = _period_bounds(first_idx, kind)
    if first_start > period.end:
        return None
    lo = max(period.start, first_start)
    idx = _calendar_start_index(lo, kind)
    last_idx = _calendar_start_index(period.end, kind)
    total = Fraction(0)
    # Whole periods strictly between the first and last overlapping ones count 1 each.
    while idx <= last_idx:
        ps, pe = _period_bounds(idx, kind)
        if ps >= lo and pe <= period.end and idx != last_idx:
            # every period from here up to (not including) last_idx is whole
            n_whole = (last_idx - idx) // months
            total += n_whole
            idx += n_whole * months
            continue
        s = max(ps, lo)
        e = min(pe, period.end)
        total += Fraction((e - s).days + 1, (pe - ps).days + 1)
        idx += months
    return total


def allowance(budget, period):
    """The Money allowance of `budget` over `period`, or None when not in force."""
    frac = _allowance_fraction(budget, period)
    if frac is None:
        return None
    exact = budget.amount.minor * frac
    return Money(round_div(exact.numerator, exact.denominator), budget.amount.currency)


def _percent(actual, budget):
    if budget == 0:
        return Decimal("0.0") if actual == 0 else Decimal("100.0")
    tenths = round_div(actual * 1000, budget)
    sign = "-" if tenths < 0 else ""
    q, r = divmod(abs(tenths), 10)
    return Decimal("%s%d.%d" % (sign, q, r))


def budget_status(budgets, ledger, period):
    """The status of each budget in force over `period`, as a list of BudgetLine."""
    from tallybook.ledger import Ledger

    try:
        budgets = list(budgets)
    except TypeError:
        raise BudgetError("budgets must be a list of Budget") from None
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a Budget: %r" % (b,))
    if not isinstance(ledger, Ledger):
        raise BudgetError("not a Ledger: %r" % (ledger,))
    if not isinstance(period, Period):
        raise BudgetError("not a Period: %r" % (period,))

    # Expense postings within the period, summed per (account, currency).
    sums = {}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        if p.amount is None or p.account.split(":", 1)[0] != "Expenses":
            continue
        key = (p.account, p.amount.currency)
        sums[key] = sums.get(key, 0) + p.amount.minor

    order = sorted(range(len(budgets)),
                   key=lambda i: (budgets[i].pattern, _KIND_ORDER[budgets[i].period_kind],
                                  budgets[i].start, i))
    lines = []
    for i in order:
        b = budgets[i]
        allowed = allowance(b, period)
        if allowed is None:
            continue
        cur = b.amount.currency
        per_account = {}
        for (acct, c), v in sums.items():
            if c == cur and b.matches(acct):
                per_account[acct] = per_account.get(acct, 0) + v
        actual_minor = sum(per_account.values())
        accounts = tuple((a, Money(v, cur)) for a, v in sorted(per_account.items()) if v != 0)
        actual = Money(actual_minor, cur)
        lines.append(BudgetLine(
            b.pattern, b.period_kind, allowed, actual, allowed - actual,
            _percent(actual_minor, allowed.minor), actual_minor > allowed.minor, accounts))
    return lines


__all__ = ["Budget", "BudgetError", "BudgetLine", "budget_status"]

