"""Recurring transactions: schedules in plain words and dated copies of a template."""
import datetime as _dt
import re

from tallybook._util import is_date, is_int
from tallybook.dates import DateError, format_date, last_day, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Transaction


class RecurringError(ValidationError):
    """A malformed schedule or recurring item."""


SHAPES = ("daily, weekly on DAY (mon tue wed thu fri sat sun), monthly on N (1-31), "
          "monthly on last, yearly on MM-DD, every N days|weeks|months|years from YYYY-MM-DD")

_DAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_DAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August",
                "September", "October", "November", "December")
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
          "month": "month", "months": "month", "year": "year", "years": "year"}

_MIN_ORD = _dt.date.min.toordinal()
_MAX_ORD = _dt.date.max.toordinal()
_MIN_MIDX = 1 * 12           # month index of 0001-01
_MAX_MIDX = 9999 * 12 + 11   # month index of 9999-12


def _bad(text):
    shown = "'%s'" % text if isinstance(text, str) else repr(text)
    return RecurringError("invalid schedule %s: expected one of: %s" % (shown, SHAPES))


def _ceil_div(a, b):
    return -((-a) // b)


def _from_ord(o):
    if _MIN_ORD <= o <= _MAX_ORD:
        return _dt.date.fromordinal(o)
    return None


def _midx(d):
    return d.year * 12 + d.month - 1


def _date_in_month(idx, day):
    """The day `day` (clamped; 0 means last) of month index idx, or None outside the calendar."""
    if not _MIN_MIDX <= idx <= _MAX_MIDX:
        return None
    y, m0 = divmod(idx, 12)
    ld = last_day(y, m0 + 1)
    return _dt.date(y, m0 + 1, ld if day == 0 else min(day, ld))


class Schedule:
    """An immutable rhythm of dates.

    Internally a schedule is a strictly increasing sequence of dates indexed by integers k;
    `_date_at(k)` is the k-th date (None outside the calendar or the sequence) and
    `_first_k(d)` the smallest index whose date is on or after d.
    """

    __slots__ = ("_key",)

    def __init__(self, text):
        if isinstance(text, Schedule):
            key = text._key
        else:
            key = _parse_key(text)
        object.__setattr__(self, "_key", key)

    @classmethod
    def parse(cls, text):
        return cls(text)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __reduce__(self):
        return (Schedule, (str(self),))

    @property
    def kind(self):
        """"daily", "weekly", "monthly", "yearly" or "every"."""
        return self._key[0]

    def __eq__(self, other):
        if not isinstance(other, Schedule):
            return NotImplemented
        return self._key == other._key

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key)

    def __str__(self):
        k = self._key
        if k[0] == "daily":
            return "daily"
        if k[0] == "weekly":
            return "weekly on %s" % _DAYS[k[1]]
        if k[0] == "monthly":
            return "monthly on %s" % ("last" if k[1] == 0 else k[1])
        if k[0] == "yearly":
            return "yearly on %02d-%02d" % (k[1], k[2])
        _, n, unit, start = k
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", format_date(start))

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    # -- indexing -----------------------------------------------------------
    def _date_at(self, k):
        key = self._key
        kind = key[0]
        if kind == "daily":
            return _from_ord(k)
        if kind == "weekly":
            # ordinal 1 (0001-01-01) is a Monday
            return _from_ord(7 * k + 1 + key[1])
        if kind == "monthly":
            return _date_in_month(k, key[1])
        if kind == "yearly":
            if not 1 <= k <= 9999:
                return None
            month, day = key[1], key[2]
            return _dt.date(k, month, min(day, last_day(k, month)))
        _, n, unit, start = key
        if k < 0:
            return None
