    k = schedule._key
    if k[0] == "daily":
        return "every day"
    if k[0] == "weekly":
        return "every %s" % _DAY_NAMES[k[1]]
    if k[0] == "monthly":
        if k[1] == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(k[1])
    if k[0] == "yearly":
        return "every year on %d %s" % (k[2], _MONTH_NAMES[k[1] - 1])
    _, n, unit, start = k
    if n == 1:
        return "every %s from %s" % (unit, format_date(start))
    return "every %d %ss from %s" % (n, unit, format_date(start))


